import java.util.*;

public class Main {
    static <T extends Comparable<T>> T max(T a, T b) { return a.compareTo(b) >= 0 ? a : b; }
    static double sum(List<? extends Number> xs) {
        double t = 0;
        for (Number n : xs) t += n.doubleValue();
        return t;
    }
    static void fill(List<? super Integer> out, int n) {
        for (int i = 0; i < n; i++) out.add(i);
    }

    public static void main(String[] args) {
        System.out.println(max("pear", "apple"));
        System.out.println(max(3, 9));
        System.out.println(sum(List.of(1, 2.5, 3)));
        List<Object> sink = new ArrayList<>();
        fill(sink, 3);
        System.out.println(sink);
    }
}

