import java.util.*;
import java.util.concurrent.*;

public class Main {
    public static void main(String[] args) throws Exception {
        ExecutorService ex = Executors.newFixedThreadPool(3);
        List<Future<Integer>> fs = new ArrayList<>();
        for (int i = 1; i <= 3; i++) {
            final int n = i;
            fs.add(ex.submit(() -> n * n));
        }
        List<Integer> out = new ArrayList<>();
        for (Future<Integer> f : fs) out.add(f.get());
        ex.shutdown();
        System.out.println(out);

        CompletableFuture<Integer> a = CompletableFuture.supplyAsync(() -> 6);
        CompletableFuture<Integer> b = CompletableFuture.supplyAsync(() -> 7);
        System.out.println(a.thenCombine(b, (x, y) -> x * y).join());

        int r = CompletableFuture.<Integer>supplyAsync(() -> { throw new IllegalStateException("boom"); })
                .exceptionally(e -> -1).join();
        System.out.println(r);
    }
}

