interface Discount {
    int apply(int price);
    default Discount then(Discount next) {
        return p -> next.apply(apply(p));
    }
}
enum Registry { INSTANCE }

final class Req {
    final String url; final int retries;
    private Req(Builder b) { url = b.url; retries = b.retries; }
    static class Builder {
        String url = "/"; int retries = 1;
        Builder url(String u) { url = u; return this; }
        Builder retries(int r) { retries = r; return this; }
        Req build() { return new Req(this); }
    }
    @Override public String toString() { return url + " retries=" + retries; }
}

public class Main {
    static Discount percent(int pct) { return p -> p - p * pct / 100; }
    static Discount flat(int amount) { return p -> p - amount; }

    public static void main(String[] args) {
        System.out.println(percent(10).apply(100));
        System.out.println(flat(5).apply(100));
        System.out.println(percent(10).then(flat(5)).apply(100));
        System.out.println(Registry.INSTANCE == Registry.valueOf("INSTANCE"));
        System.out.println(new Req.Builder().url("/x").retries(3).build());
